const body = $json.body || $json;
const callbackQuery = body.callback_query || body;

const callbackId = callbackQuery.id || 'N/A';
const callbackData = callbackQuery.data || '';
const user = callbackQuery.from ? (callbackQuery.from.username || callbackQuery.from.first_name || 'SOC_Analyst') : 'SOC_Analyst';
const chatId = callbackQuery.message && callbackQuery.message.chat ? callbackQuery.message.chat.id : '8696241190';
const messageId = callbackQuery.message ? callbackQuery.message.message_id : null;

// Format: action:<type>:<target_ip/rule>:<alert_id> or action:jira:<rule_id>:<target_ip>:<alert_id>
const parts = callbackData.split(':');
const actionType = parts[1] || 'unknown';
let ruleId = 'N/A';
let targetParam = 'N/A';
let alertId = 'N/A';

if (actionType === 'jira') {
  ruleId = parts[2] || 'N/A';
  targetParam = parts[3] || 'N/A';
  alertId = parts[4] || 'N/A';
} else {
  targetParam = parts[2] || 'N/A';
  alertId = parts[3] || 'N/A';
}

// Safety fallback for targetParam if N/A
if (!targetParam || targetParam === 'N/A' || targetParam === '-') {
  targetParam = '192.168.71.129 (DESKTOP-A2AG7TR)';
}

return {
  callback_id: callbackId,
  chat_id: chatId,
  message_id: messageId,
  action: actionType,
  rule_id: ruleId,
  target: targetParam,
  alert_id: alertId,
  operator: user,
  ack_text: 'Action acknowledged: ' + actionType.toUpperCase(),
  timestamp: new Date().toISOString()
};

const item = $('Parse Callback & Intent').item.json;
const text = `🔒 <b>[SOAR CONTAINMENT EXECUTED]</b>\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `🛡️ <b>Action:</b> Host Isolation & Malicious IP Firewall Drop\n` +
  `🎯 <b>Target / IOC:</b> <code>${item.target}</code>\n` +
  `🆔 <b>Alert ID:</b> <code>${item.alert_id}</code>\n` +
  `👤 <b>Approving Analyst:</b> @${item.operator}\n` +
  `⏱️ <b>Block Duration:</b> 24 Hours\n` +
  `✅ <b>Status:</b> Active Response firewall rule deployed (Inbound/Outbound DROP)\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `<i>To revert containment or restore access immediately, click below:</i>`;

const inlineKeyboard = {
  inline_keyboard: [
    [
      { text: '🟢 [Unblock IP (Rollback)]', callback_data: `action:unblock:${item.target}:${item.alert_id}` }
    ]
  ]
};

return {
  action: 'block',
  target_ip: item.target,
  chat_id: item.chat_id || '8696241190',
  text: text,
  reply_markup: inlineKeyboard
};

const item = $('Parse Callback & Intent').item.json;
const text = `⚠️ <b>[SOAR ALERT ACKNOWLEDGED - FALSE POSITIVE]</b>\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `ℹ️ <b>Decision:</b> Alert Dismissed / False Positive\n` +
  `🎯 <b>Target / Artifact:</b> <code>${item.target}</code>\n` +
  `🆔 <b>Alert ID:</b> <code>${item.alert_id}</code>\n` +
  `👤 <b>Analyst:</b> @${item.operator}\n` +
  `📝 <b>Notes:</b> Event recorded in SOAR audit trail as False Positive.`;

return {
  action: 'ignore',
  target: item.target,
  chat_id: item.chat_id || '8696241190',
  text: text
};

const item = $('Parse Callback & Intent').item.json;
const isDeception = ['100014', '100015', '100016'].includes(String(item.rule_id));

let summary = `[Wazuh SOAR Incident] Rule ${item.rule_id} on ${item.target}`;
let desc = '';

if (isDeception) {
  summary = `[HONEYPOT BREACH - P1 URGENT] Deception Tripwire Triggered (Rule ${item.rule_id})`;
  desc = `🚨 AUTOMATED DECEPTION TRIPWIRE BREACH DISPATCH\n\n` +
    `• Alert ID: ${item.alert_id}\n` +
    `• Triggered Rule ID: ${item.rule_id}\n` +
    `• Attacker Source / Target: ${item.target}\n` +
    `• Triage Operator: @${item.operator}\n` +
    `• Severity Level: Critical (P1 Urgent)\n` +
    `• Forensics Evidence: Digital Forensics Archive (.ZIP) captured and attached.\n` +
    `• Incident Response: Active containment action deployed via DevSecOps SOAR Pipeline.`;
} else {
  desc = `Automated Security Incident Ticket dispatched by Wazuh-n8n DevSecOps Pipeline.\n\n` +
    `• Alert ID: ${item.alert_id}\n` +
    `• Triggered Rule ID: ${item.rule_id}\n` +
    `• Attacker Source / Target: ${item.target}\n` +
    `• Triage Operator: @${item.operator}\n` +
    `• Severity Level: High\n` +
    `• Recommended Action: Immediate Tier-2 SOC Analyst investigation required. Perform host artifact triage, review process tree, examine telemetry logs, and verify containment status.`;
}

const email = $env.JIRA_EMAIL || 'tn421015@gmail.com';
const token = $env.JIRA_API_TOKEN || '';
const authHeader = 'Basic ' + Buffer.from(email + ':' + token).toString('base64');

return {
  auth_header: authHeader,
  fields: {
    project: { key: $env.JIRA_PROJECT_KEY || 'KAN' },
    summary: summary,
    description: {
      type: 'doc',
      version: 1,
      content: [
        {
          type: 'paragraph',
          content: [
            {
              type: 'text',
              text: desc
            }
          ]
        }
      ]
    },
    issuetype: { name: 'Task' },
    priority: { name: 'High' }
  }
};

const item = $('Parse Callback & Intent').item.json;
const jiraKey = $json.key || null;
const jiraUrl = jiraKey ? `https://tn421015.atlassian.net/browse/${jiraKey}` : '';

let text = '';
if (jiraKey) {
  text = `📋 <b>[JIRA CASE MANAGEMENT - TICKET OPENED]</b>\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `🎫 <b>Ticket Key:</b> <code>${jiraKey}</code>\n` +
    `🔗 <b>Direct URL:</b> <a href="${jiraUrl}">Open Ticket on Jira Cloud</a>\n` +
    `🎯 <b>Target/IOC:</b> <code>${item.target}</code>\n` +
    `🆔 <b>Alert ID:</b> <code>${item.alert_id}</code>\n` +
    `👤 <b>Reporter:</b> @${item.operator}\n` +
    `🚨 <b>Priority:</b> High\n` +
    `📌 <b>Workflow Status:</b> Incident ticket transferred to Tier-2 SOC Investigation Queue.`;
} else {
  const errDetails = $json.error ? ($json.error.message || JSON.stringify($json.error)) : JSON.stringify($json);
  text = `❌ <b>[JIRA CASE MANAGEMENT - CREATION FAILED]</b>\n` +
    `━━━━━━━━━━━━━━━━━━━━━━\n` +
    `⚠️ <b>Error Details:</b> <code>${errDetails.substring(0, 200)}</code>\n` +
    `🎯 <b>Target/IOC:</b> <code>${item.target}</code>\n` +
    `🆔 <b>Alert ID:</b> <code>${item.alert_id}</code>`;
}

return {
  chat_id: item.chat_id || '8696241190',
  text: text
};

const item = $('Parse Callback & Intent').item.json;
const text = `🟢 <b>[SOAR ROLLBACK EXECUTED - ACCESS RESTORED]</b>\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `🔓 <b>Action:</b> Firewall Unblock & Host Isolation Reverted\n` +
  `🎯 <b>Target / IOC:</b> <code>${item.target}</code>\n` +
  `🆔 <b>Alert ID:</b> <code>${item.alert_id}</code>\n` +
  `👤 <b>Approving Analyst:</b> @${item.operator}\n` +
  `⚙️ <b>Remediation:</b> <code>Remove-NetFirewallRule -DisplayName "SOAR-BLOCK-*"</code>\n` +
  `✅ <b>Status:</b> Network traffic successfully restored (Zero-Downtime Recovery)`;

return {
  action: 'unblock',
  target: item.target,
  chat_id: item.chat_id || '8696241190',
  text: text
};

const item = $('Parse Callback & Intent').item.json;
const procName = item.target.includes('.exe') ? item.target : `${item.target}.exe`;
const cleanTarget = procName.replace('.exe', '');
const text = `🛑 <b>[SOAR PROCESS TERMINATION EXECUTED]</b>\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `⚔️ <b>Action:</b> Host-Level Threat Termination (Kill Malicious Process)\n` +
  `⚙️ <b>Target Process:</b> <code>${procName}</code>\n` +
  `🆔 <b>Alert ID:</b> <code>${item.alert_id}</code>\n` +
  `👤 <b>Approving Analyst:</b> @${item.operator}\n` +
  `💻 <b>Endpoint:</b> <code>192.168.71.129 (DESKTOP-A2AG7TR)</code>\n` +
  `⚙️ <b>Remediation Command:</b> <code>Stop-Process -Name "${cleanTarget}" -Force</code>\n` +
  `✅ <b>Status:</b> Suspicious execution thread severed; attacker interactive session terminated.`;

return {
  action: 'killproc',
  target: procName,
  chat_id: item.chat_id || '8696241190',
  text: text
};
